            started?: boolean;
            finished?: boolean;
            /** @description The minute playing now (minutes made ahead of time do not count yet) */
            tick?: number;
            /** @description Server clock in ms */
            server_now?: number;
            /** @description When the next minute is due (ms) */
            next_at?: number | null;
            /** @description Some minutes after `since` are no longer kept; jump to the latest */
            gap?: boolean;
